-- ===== 20260927100030_gis_accessibility.sql =====
-- Agent 3: server-side corridor accessibility (checklist 2: GIS accessibility dashboard).
--
-- get_corridor_accessibility(p_district) returns, per stored route:
--   status          open | restricted | blocked
--   open_length_pct    share of the route length not affected by open incidents
--                      (blocked stretch counts 0, restricted stretch counts 0.5); null without geometry
--   accessibility_pct  0 when blocked, else open_length_pct
--   incidents       open incidents on the route (route_id match, or within 1 km of its line)
--   ml              mean / max risk percentile of ML segments within 100 m (latest published run)
--
-- Incident scope mirrors road_incidents RLS: control room sees every district (optionally narrowed by
-- p_district, a district name); district / field officers see only their own district. Riders are refused.
--
-- plpgsql on purpose: the body is resolved at call time, so this applies before Agent 6's
-- 20260927100060_field_reporting.sql and uses only road_incidents columns from the core schema.

create or replace function public.get_corridor_accessibility(p_district text default null)
returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_role   text := public.my_role();
  v_scope  uuid;
  v_all    boolean;
  v_run    public.ml_batch_runs;
  v_routes jsonb;
begin
  if not public.is_officer() then raise exception 'officers only' using errcode = '42501'; end if;

  if v_role = 'control_room' then
    v_all := nullif(trim(p_district), '') is null;
    if not v_all then
      select l.id into v_scope from public.locations l
       where l.kind = 'district' and lower(l.district) = lower(trim(p_district)) limit 1;
    end if;
  else
    select ur.district_id into v_scope from public.user_roles ur where ur.user_id = auth.uid() and ur.is_active;
    v_all := false;
  end if;

  v_run := public.ml_pick_run(null);

  with inc as (
    select i.id, i.incident_type, i.severity, i.status, i.route_id, i.district_id, i.location, i.created_at,
           (select l.district from public.locations l where l.id = i.district_id) as district,
           -- blocking needs a confirmed report; an unconfirmed critical one only restricts
           (i.status in ('verified', 'active', 'assigned', 'escalated')
             and (i.severity = 'critical' or (i.incident_type in ('road_blockage', 'landslide', 'flood') and i.severity = 'high')))
             as blocks
    from public.road_incidents i
    where i.status not in ('resolved', 'rejected')
      and (v_all or i.district_id = v_scope)
  ),
  per_route as (
    select r.id, r.route_number, r.name, r.origin, r.destination, r.geom,
           extensions.st_length(r.geom) as len_m,
           coalesce((select jsonb_agg(jsonb_build_object(
                       'id', x.id, 'incident_type', x.incident_type, 'severity', x.severity,
                       'status', x.status, 'blocks', x.blocks, 'created_at', x.created_at, 'district', x.district,
                       'lat', extensions.st_y(x.location::extensions.geometry),
                       'lon', extensions.st_x(x.location::extensions.geometry)) order by x.blocks desc, x.created_at desc)
                     from inc x
                     where x.route_id = r.id
                        or (r.geom is not null and x.location is not null and extensions.st_dwithin(x.location, r.geom, 1000))),
                    '[]'::jsonb) as incidents
    from public.routes r
  ),
  scored as (
    select p.*,
           case when exists (select 1 from jsonb_array_elements(p.incidents) e where (e->>'blocks')::boolean) then 'blocked'
                when jsonb_array_length(p.incidents) > 0 then 'restricted'
                else 'open' end as status,
           -- length of the line within 1 km of blocking / other open incidents
           (select extensions.st_length(extensions.st_intersection(p.geom::extensions.geometry,
                     extensions.st_union(extensions.st_buffer(x.location, 1000)::extensions.geometry))::extensions.geography)
              from inc x where x.blocks and x.location is not null and p.geom is not null
               and extensions.st_dwithin(x.location, p.geom, 1000)) as blocked_m,
           (select extensions.st_length(extensions.st_intersection(p.geom::extensions.geometry,
                     extensions.st_union(extensions.st_buffer(x.location, 1000)::extensions.geometry))::extensions.geography)
              from inc x where not x.blocks and x.location is not null and p.geom is not null
               and extensions.st_dwithin(x.location, p.geom, 1000)) as restricted_m,
           (select jsonb_build_object('n_segments', count(*), 'n_alert', count(*) filter (where sc.tier = 'alert'),
                                      'mean_percentile', round(avg(sc.risk_percentile)::numeric, 1),
                                      'max_percentile', max(sc.risk_percentile))
              from public.ml_segments s
              join ml_private.segment_scores sc on sc.run_id = v_run.id and sc.segment_id = s.segment_id
             where v_run.id is not null and p.geom is not null and extensions.st_dwithin(s.geom, p.geom, 100)) as ml
    from per_route p
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'route_id', s.id, 'route_number', s.route_number, 'name', s.name,
           'origin', s.origin, 'destination', s.destination,
           'status', s.status,
           'has_geometry', s.geom is not null,
           'length_m', round(s.len_m::numeric),
           'open_length_pct', s.open_pct,
           -- a blocked corridor is cut for through traffic, whatever share of it is still clear
           'accessibility_pct', case when s.status = 'blocked' then 0 else s.open_pct end,
           'blocking_incidents', (select count(*) from jsonb_array_elements(s.incidents) e where (e->>'blocks')::boolean),
           'open_incidents', jsonb_array_length(s.incidents),
           'incidents', s.incidents,
           'ml', case when v_run.id is null or s.geom is null then null else s.ml end,
           'geojson', case when s.geom is null then null
                           else extensions.st_asgeojson(extensions.st_simplify(s.geom::extensions.geometry, 0.0005), 5)::jsonb end
         ) order by s.route_number), '[]'::jsonb)
    into v_routes
    from (select sc.*, case when sc.len_m > 0 then greatest(0, round((100 * (1
                 - (coalesce(sc.blocked_m, 0) + 0.5 * greatest(coalesce(sc.restricted_m, 0) - coalesce(sc.blocked_m, 0), 0)) / sc.len_m))::numeric, 1))
               end as open_pct
          from scored sc) s;

  return jsonb_build_object(
    'generated_at', now(),
    'scope', case when v_all then 'region' else coalesce(v_scope::text, 'none') end,
    'ml', public.ml_meta(v_run),
    'routes', v_routes);
end $$;

revoke execute on function public.get_corridor_accessibility(text) from public, anon;
grant execute on function public.get_corridor_accessibility(text) to authenticated;

-- ===== 20260927100040_gps_tracking_rider_scope.sql =====
-- Rider visibility by scope (Agent 4, GPS tracking).
-- Before: every officer role read every rider's position. Now control_room sees all riders;
-- district_officer and field_officer see only riders assigned to their own district.
-- Covers table reads, Realtime postgres_changes (RLS-filtered) and the two officer RPCs.

create function public.can_see_rider(p_rider uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select case
    when public.my_role() = 'control_room' then true
    when public.my_role() in ('district_officer', 'field_officer') then exists (
      select 1 from public.user_roles me
      join public.user_roles r on r.district_id = me.district_id
      where me.user_id = auth.uid() and r.user_id = p_rider)
    else false
  end
$$;

revoke execute on function public.can_see_rider(uuid) from public, anon;  -- Agent 7: PUBLIC keeps execute by default
grant execute on function public.can_see_rider(uuid) to authenticated;

drop policy rider_profiles_officer on public.rider_profiles;
drop policy rider_locations_officer on public.rider_locations;
drop policy rider_history_officer on public.rider_location_history;
create policy rider_profiles_officer on public.rider_profiles for select to authenticated
  using (public.can_see_rider(user_id));
create policy rider_locations_officer on public.rider_locations for select to authenticated
  using (public.can_see_rider(user_id));
create policy rider_history_officer on public.rider_location_history for select to authenticated
  using (public.can_see_rider(user_id));

-- Same body as 20260924000003, plus the scope filter.
create or replace function public.get_active_riders(p_stale_minutes integer default 30)
returns table (
  user_id uuid, full_name text, officer_id text, phone text, district text,
  vehicle_registration text, vehicle_type text, is_on_duty boolean,
  latitude double precision, longitude double precision, accuracy_m real, speed_kmph real,
  heading_deg real, battery_percent smallint, is_moving boolean,
  recorded_at timestamptz, received_at timestamptz, is_stale boolean,
  shipment_id uuid, shipment_number text, shipment_status text, cargo_description text,
  risk_level text, origin_name text, destination_name text, route_number text,
  estimated_arrival timestamptz
)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_officer() then
    raise exception 'officers only' using errcode = '42501';
  end if;
  return query
  select l.user_id, p.full_name, p.officer_id, coalesce(rp.phone, p.phone), loc.name,
         rp.vehicle_registration, rp.vehicle_type, coalesce(rp.is_on_duty, false),
         l.latitude, l.longitude, l.accuracy_m, l.speed_kmph, l.heading_deg, l.battery_percent, l.is_moving,
         l.recorded_at, l.received_at, l.recorded_at < now() - make_interval(mins => p_stale_minutes),
         s.id, s.shipment_number, s.status, s.cargo_description, s.risk_level,
         s.origin, s.destination, r.route_number, s.estimated_arrival
  from public.rider_locations l
  join public.profiles p on p.id = l.user_id
  left join public.rider_profiles rp on rp.user_id = l.user_id
  left join public.user_roles ur on ur.user_id = l.user_id
  left join public.locations loc on loc.id = ur.district_id
  left join public.shipments s on s.id = l.shipment_id
  left join public.routes r on r.id = s.route_id
  where (coalesce(rp.is_on_duty, false) or l.recorded_at > now() - interval '24 hours')
    and public.can_see_rider(l.user_id)
  order by l.recorded_at desc;
end $$;

create or replace function public.get_rider_trail(p_user_id uuid, p_since timestamptz, p_limit integer default 500)
returns table (latitude double precision, longitude double precision, speed_kmph real, recorded_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_officer() or not public.can_see_rider(p_user_id) then
    raise exception 'rider not in your scope' using errcode = '42501';
  end if;
  return query
  select h.latitude, h.longitude, h.speed_kmph, h.recorded_at
  from public.rider_location_history h
  where h.user_id = p_user_id and h.recorded_at >= p_since
  order by h.recorded_at desc
  limit least(greatest(p_limit, 1), 2000);
end $$;

-- ===== 20260927100050_alerts_notifications.sql =====
-- Alert pipeline (DELIVERY_GAP_PLAN 3.3): acknowledge/resolve RPC, per-user notification
-- preferences, FCM device tokens, and high-severity road incidents raising alerts.
-- The delivery webhook (alerts INSERT -> notify edge function) is NOT here: it needs the
-- project URL and a shared secret in Vault. See supabase/functions/notify/webhook.sql.

-- Alerts: who resolved it ----------------------------------------------------------------------
alter table public.alerts
  add column resolved_by uuid references auth.users (id),
  add column resolved_at timestamptz;
create index alerts_created_idx on public.alerts (created_at desc);

-- Officers see alerts for their own district plus district-less ones (ML, statewide); the control
-- room sees all. Mirrors the road_incidents scoping in 20260927100060 (inline: that helper is created later).
create function public.alert_in_my_scope(p_district uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select public.has_role('control_room')
      or (public.is_officer() and (p_district is null or p_district =
            (select ur.district_id from public.user_roles ur where ur.user_id = auth.uid())))
$$;
drop policy alerts_read on public.alerts;
drop policy alerts_update on public.alerts;
create policy alerts_read on public.alerts for select to authenticated using (public.alert_in_my_scope(district_id));
create policy alerts_update on public.alerts for update to authenticated
  using (public.alert_in_my_scope(district_id)) with check (public.alert_in_my_scope(district_id));

-- Acknowledge / resolve. The actor is always auth.uid(); clients can't claim someone else did it.
create function public.set_alert_status(p_alert_id uuid, p_status text)
returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_officer() then raise exception 'officers only' using errcode = '42501'; end if;
  if p_status not in ('acknowledged', 'resolved') then
    raise exception 'status must be acknowledged or resolved' using errcode = '22023';
  end if;
  update public.alerts a set
    status          = case when a.status = 'resolved' then a.status else p_status end,
    acknowledged_by = coalesce(a.acknowledged_by, auth.uid()),
    acknowledged_at = coalesce(a.acknowledged_at, now()),
    resolved_by     = case when p_status = 'resolved' then coalesce(a.resolved_by, auth.uid()) else a.resolved_by end,
    resolved_at     = case when p_status = 'resolved' then coalesce(a.resolved_at, now()) else a.resolved_at end
  where a.id = p_alert_id and public.alert_in_my_scope(a.district_id);
  if not found then raise exception 'alert not found' using errcode = 'P0002'; end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, detail)
  values (auth.uid(), 'alert_' || p_status, 'alerts', p_alert_id::text, null);
end $$;

-- Notification preferences: one row per user; a missing row means the defaults below. ----------
create table public.notification_prefs (
  user_id    uuid primary key references auth.users (id) on delete cascade default auth.uid(),
  push       boolean not null default true,
  email      boolean not null default true,
  sms        boolean not null default false,
  updated_at timestamptz not null default now()
);
create trigger notification_prefs_touch before update on public.notification_prefs
  for each row execute function public.touch_updated_at();

alter table public.notification_prefs enable row level security;
create policy notification_prefs_own on public.notification_prefs for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
grant select, insert, update on public.notification_prefs to authenticated;

-- FCM registration tokens. Written through register_device_token so a phone that changes hands
-- moves its token to the new user (a plain upsert would hit the old owner's row under RLS).
create table public.device_tokens (
  token      text primary key,
  user_id    uuid not null references auth.users (id) on delete cascade,
  platform   text not null check (platform in ('android', 'ios', 'web')),
  updated_at timestamptz not null default now()
);
create index device_tokens_user_idx on public.device_tokens (user_id);

alter table public.device_tokens enable row level security;
create policy device_tokens_own_read   on public.device_tokens for select to authenticated using (user_id = auth.uid());
create policy device_tokens_own_delete on public.device_tokens for delete to authenticated using (user_id = auth.uid());
grant select, delete on public.device_tokens to authenticated;

create function public.register_device_token(p_token text, p_platform text)
returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_active_user() then raise exception 'sign in required' using errcode = '42501'; end if;
  if coalesce(length(p_token), 0) not between 20 and 4096 then
    raise exception 'invalid token' using errcode = '22023';
  end if;
  insert into public.device_tokens (token, user_id, platform, updated_at)
  values (p_token, auth.uid(), p_platform, now())
  on conflict (token) do update set user_id = excluded.user_id, platform = excluded.platform, updated_at = now();
end $$;

revoke execute on function public.set_alert_status(uuid, text), public.register_device_token(text, text), public.alert_in_my_scope(uuid) from public, anon;
grant execute on function public.set_alert_status(uuid, text), public.register_device_token(text, text), public.alert_in_my_scope(uuid) to authenticated;

-- High/critical road incidents raise an alert --------------------------------------------------
-- plpgsql + to_jsonb(new): reads Agent 6's optional title/location_text when that migration has
-- run, without depending on those columns at CREATE time.
create function public.raise_alert_from_incident()
returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  j       jsonb := to_jsonb(new);
  v_label text  := initcap(replace(new.incident_type, '_', ' '));
begin
  insert into public.alerts (title, description, severity, source, district_id, route_id, incident_id, created_by)
  values (
    coalesce(nullif(j->>'title', ''), v_label || ' reported')
      || coalesce(' · ' || nullif(j->>'location_text', ''), ''),
    new.description,
    new.severity,
    'rule',
    new.district_id,
    new.route_id,
    new.id,
    new.reporter_id
  );
  return new;
end $$;

create trigger road_incidents_raise_alert after insert on public.road_incidents
  for each row when (new.severity in ('critical', 'high'))
  execute function public.raise_alert_from_incident();
revoke execute on function public.raise_alert_from_incident() from public, anon, authenticated;  -- Agent 7: trigger-only

-- ===== 20260927100060_field_reporting.sql =====
-- Field reporting: persist incidents and tasks (DELIVERY_GAP_PLAN 3.2).
--   * road_incidents gains the fields the web/Flutter clients show, plus plain lat/lng.
--   * field_tasks: follow-up work created from an incident, with a verification step.
--   * Private Storage bucket incident-evidence for photos/videos.
--   * RLS scoped by role and district: control room sees everything, district and field officers
--     see their own district, reporters and assignees always see their own rows.

-- Helpers ---------------------------------------------------------------------------------------
create function public.my_district_id() returns uuid
language sql stable security definer set search_path = '' as $$
  select ur.district_id from public.user_roles ur where ur.user_id = auth.uid() and ur.is_active
$$;

-- True when the caller may see/act on rows of this district (control room: every district).
create function public.in_my_scope(p_district uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(
    public.has_role('control_room')
    or (public.my_role() in ('district_officer', 'field_officer') and p_district = public.my_district_id()),
    false)
$$;

-- road_incidents ------------------------------------------------------------------------------
alter table public.road_incidents
  add column title          text,
  add column location_text  text,
  add column route_text     text,
  add column lat            double precision check (lat between -90 and 90),
  add column lng            double precision check (lng between -180 and 180),
  add column verification   text not null default 'pending' check (verification in ('pending', 'verified', 'rejected')),
  add column assigned_to    uuid references auth.users (id),
  add column evidence_paths text[] not null default '{}',
  alter column reporter_id set default auth.uid();

-- Web status values need two more states: under_review and active (verified, work under way).
alter table public.road_incidents drop constraint road_incidents_status_check;
alter table public.road_incidents add constraint road_incidents_status_check
  check (status in ('reported', 'under_review', 'verified', 'active', 'assigned', 'escalated', 'resolved', 'rejected'));

create index road_incidents_district_idx on public.road_incidents (district_id, created_at desc);
create index road_incidents_reporter_idx on public.road_incidents (reporter_id);
create index road_incidents_assigned_idx on public.road_incidents (assigned_to) where assigned_to is not null;
create index road_incidents_evidence_idx on public.road_incidents using gin (evidence_paths);

-- Fill district from the reporter, geography from lat/lng, and verified_by on verification.
create function public.road_incidents_fill() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    new.district_id := coalesce(new.district_id, public.my_district_id());
  end if;
  if new.lat is not null and new.lng is not null then
    new.location := extensions.st_setsrid(extensions.st_makepoint(new.lng, new.lat), 4326)::extensions.geography;
  end if;
  if new.verification is distinct from 'pending'
     and (tg_op = 'INSERT' or new.verification is distinct from old.verification) then
    new.verified_by := auth.uid();
  end if;
  return new;
end $$;
create trigger road_incidents_fill before insert or update on public.road_incidents
  for each row execute function public.road_incidents_fill();

-- Replace the read-everything officer policies with district-scoped ones.
drop policy incidents_read_officer   on public.road_incidents;
drop policy incidents_officer_update on public.road_incidents;
create policy incidents_read_scope on public.road_incidents for select to authenticated
  using (public.in_my_scope(district_id) or assigned_to = auth.uid());
create policy incidents_update_scope on public.road_incidents for update to authenticated
  using (public.in_my_scope(district_id) or assigned_to = auth.uid())
  with check (public.in_my_scope(district_id) or assigned_to = auth.uid());
-- incidents_read_own and incidents_insert (reporter_id = auth.uid()) stay as they are.

-- field_tasks ---------------------------------------------------------------------------------
create table public.field_tasks (
  id                uuid primary key default gen_random_uuid(),
  client_id         text unique,
  incident_id       uuid references public.road_incidents (id) on delete set null,
  title             text not null,
  description       text,
  location_text     text,
  priority          text not null default 'moderate' check (priority in ('critical', 'high', 'moderate', 'info')),
  status            text not null default 'new'
    check (status in ('new', 'in_progress', 'completed', 'escalated', 'awaiting_verification', 'verified', 'rejected')),
  assigned_to       uuid references auth.users (id),
  district_id       uuid references public.locations (id),
  created_by        uuid default auth.uid() references auth.users (id),
  deadline          timestamptz,
  verification_note text,
  verified_by       uuid references auth.users (id),
  assigned_at       timestamptz,
  started_at        timestamptz,
  completed_at      timestamptz,
  verified_at       timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index field_tasks_district_idx on public.field_tasks (district_id, created_at desc);
create index field_tasks_assigned_idx on public.field_tasks (assigned_to) where assigned_to is not null;
create index field_tasks_incident_idx on public.field_tasks (incident_id);

create trigger field_tasks_touch before update on public.field_tasks
  for each row execute function public.touch_updated_at();

-- Timestamps are set by the server so every client computes response time the same way.
-- Only district officers and the control room can decide a verification.
create function public.field_tasks_fill() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  v_old_status text := case when tg_op = 'UPDATE' then old.status end;
  v_old_assignee uuid := case when tg_op = 'UPDATE' then old.assigned_to end;
begin
  if tg_op = 'INSERT' then
    new.district_id := coalesce(new.district_id,
      (select ri.district_id from public.road_incidents ri where ri.id = new.incident_id),
      public.my_district_id());
  end if;
  if new.assigned_to is not null and new.assigned_to is distinct from v_old_assignee then
    new.assigned_at := now();
  end if;
  if new.status is distinct from v_old_status then
    if (new.status in ('verified', 'rejected') or v_old_status = 'verified')
       and coalesce(public.my_role() not in ('district_officer', 'control_room'), true) then
      raise exception 'Only a district officer or the control room can review a task' using errcode = '42501';
    end if;
    if new.status in ('verified', 'rejected') then
      if v_old_status is distinct from 'awaiting_verification' then
        raise exception 'Only a task awaiting verification can be reviewed' using errcode = '22023';
      end if;
      new.verified_by := auth.uid();
      new.verified_at := now();
    elsif new.status = 'awaiting_verification' then
      -- from completed (field officer asks), or back from a decision (reviewer's undo / resubmission)
      if coalesce(v_old_status not in ('completed', 'verified', 'rejected'), true) then
        raise exception 'Only a completed task can be sent for verification' using errcode = '22023';
      end if;
      new.verified_by := null;
      new.verified_at := null;
    end if;
    if new.status = 'in_progress' and new.started_at is null then new.started_at := now(); end if;
    if new.status = 'completed' and new.completed_at is null then new.completed_at := now(); end if;
  end if;
  return new;
end $$;
create trigger field_tasks_fill before insert or update on public.field_tasks
  for each row execute function public.field_tasks_fill();

alter table public.field_tasks enable row level security;
create policy field_tasks_read on public.field_tasks for select to authenticated
  using (public.in_my_scope(district_id) or assigned_to = auth.uid() or created_by = auth.uid());
create policy field_tasks_insert on public.field_tasks for insert to authenticated
  with check (created_by = auth.uid()
    and public.my_role() in ('district_officer', 'control_room')
    and public.in_my_scope(district_id));
create policy field_tasks_update on public.field_tasks for update to authenticated
  using (public.in_my_scope(district_id) or assigned_to = auth.uid())
  with check (public.in_my_scope(district_id) or assigned_to = auth.uid());
create policy field_tasks_delete on public.field_tasks for delete to authenticated
  using (public.my_role() in ('district_officer', 'control_room') and public.in_my_scope(district_id));

grant select, insert, update, delete on public.field_tasks to authenticated;

-- Realtime ------------------------------------------------------------------------------------
-- road_incidents is already in the publication (20260924000002).
alter publication supabase_realtime add table public.field_tasks;

-- Storage: incident-evidence ------------------------------------------------------------------
-- Objects live under {uploader uid}/{client_id}/{file}. The uploader reads their own folder;
-- anyone who can see an incident (RLS on road_incidents applies inside the subquery) can read
-- the files listed in its evidence_paths.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('incident-evidence', 'incident-evidence', false, 20971520,
        array['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'video/mp4', 'video/quicktime', 'video/webm'])
on conflict (id) do nothing;

create policy evidence_insert_own on storage.objects for insert to authenticated
  with check (bucket_id = 'incident-evidence'
    and (storage.foldername(name))[1] = auth.uid()::text
    and public.is_active_user());
create policy evidence_update_own on storage.objects for update to authenticated
  using (bucket_id = 'incident-evidence' and (storage.foldername(name))[1] = auth.uid()::text)
  with check (bucket_id = 'incident-evidence' and (storage.foldername(name))[1] = auth.uid()::text);
create policy evidence_read on storage.objects for select to authenticated
  using (bucket_id = 'incident-evidence' and (
    (storage.foldername(name))[1] = auth.uid()::text
    or exists (select 1 from public.road_incidents ri where storage.objects.name = any (ri.evidence_paths))));

-- Grants ----------------------------------------------------------------------------------------
revoke execute on function public.my_district_id(), public.in_my_scope(uuid),
  public.road_incidents_fill(), public.field_tasks_fill() from public, anon, authenticated;
grant execute on function public.my_district_id(), public.in_my_scope(uuid) to authenticated;

-- ===== 20260927100070_fo_parity_security.sql =====
-- Field-officer form parity (web ReportIncident == Flutter ReportScreen) and two security fixes.
--   * road_incidents gains the report fields both forms now send: landmark, road_condition,
--     vehicles_affected, estimated_blockage.
--   * A report whose reporter has no district falls back to the nearest district by GPS, so the
--     district officer sees it (previously district_id stayed null and only the control room saw it).
--   * Field officers can no longer insert a report that is already verified/active: an unreviewed
--     report could otherwise mark a corridor blocked (get_corridor_accessibility).
--   * Self-registered control_room accounts start inactive and need approval, like every officer role.

alter table public.road_incidents
  add column landmark           text,
  add column road_condition     text check (road_condition in ('fully_blocked', 'partially_accessible', 'passable_with_caution')),
  add column vehicles_affected  integer check (vehicles_affected >= 0),
  add column estimated_blockage text;

create or replace function public.road_incidents_fill() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    -- Only reviewers may create a report that skips review.
    if coalesce(public.my_role() not in ('district_officer', 'control_room'), true) then
      new.status := 'reported';
      new.verification := 'pending';
    end if;
  end if;
  if new.lat is not null and new.lng is not null then
    new.location := extensions.st_setsrid(extensions.st_makepoint(new.lng, new.lat), 4326)::extensions.geography;
  end if;
  if tg_op = 'INSERT' then
    new.district_id := coalesce(new.district_id, public.my_district_id(),
      (select l.id from public.locations l
       where new.location is not null and l.kind = 'district' and l.geom is not null
       order by l.geom operator(extensions.<->) new.location limit 1));
  end if;
  if new.verification is distinct from 'pending'
     and (tg_op = 'INSERT' or new.verification is distinct from old.verification) then
    new.verified_by := auth.uid();
  end if;
  return new;
end $$;

create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  m        jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_role   public.user_role_enum;
  v_loc    uuid;
begin
  v_role := case m->>'requested_role'
    when 'rider'            then 'rider'
    when 'district_officer' then 'district_officer'
    when 'control_room'     then 'control_room'
    else 'field_officer'
  end::public.user_role_enum;

  select l.id into v_loc from public.locations l
  where nullif(trim(m->>'district'), '') is not null
    and lower(l.name) = lower(trim(m->>'district'))
    and (nullif(trim(m->>'state'), '') is null or lower(l.state) = lower(trim(m->>'state')))
  order by l.kind = 'district' desc limit 1;

  insert into public.profiles (id, full_name, officer_id, phone, region)
  values (new.id, nullif(trim(m->>'full_name'), ''), nullif(trim(m->>'officer_id'), ''),
          nullif(trim(m->>'phone'), ''), nullif(trim(coalesce(m->>'district', m->>'state', '')), ''));

  -- Riders only are active immediately. The very first control_room account is switched on by hand:
  --   update public.user_roles set is_active = true where user_id = '<uuid>';
  insert into public.user_roles (user_id, role, district_id, is_active)
  values (new.id, v_role, v_loc, v_role = 'rider');

  if v_role = 'rider' then
    insert into public.rider_profiles (user_id, phone, vehicle_registration)
    values (new.id, nullif(trim(m->>'phone'), ''), nullif(upper(trim(m->>'vehicle_registration')), ''));
  end if;
  return new;
end $$;

revoke execute on function public.road_incidents_fill(), public.handle_new_user() from public, anon, authenticated;

commit;
